window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d3ba2ba664e307f3"]={"versions": [{"id": "FIG-d3ba2ba664e307f3", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm im TTCN-3 Graphical Presentation Format (GFT) / Message Sequence Chart (MSC).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation eines Interaktionsmusters im AUTOSAR Conformance Testing Framework (Dokument: <code>AUTOSAR_CTSpec_Creation_Validation</code>, Release R3.0.7). Das Diagramm definiert den normativen Ablauf für das synchrone Beschreiben eines zuvor auf dem Testziel (SUT) allokierten Speicherblocks über den Target Adapter (TA).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Test Component / Test Case (Rechte Lebenslinie):</strong> Führende Testkomponente (MTC/PTC), die den Testablauf steuert, Timeouts überwacht und Rückgabewerte verifiziert.\n</li><li><strong>Target Adapter / SUT (Linke Lebenslinie):</strong> Testadapter-Schicht auf Zielsystemebene, die Testprozeduren in konkrete Speicherzugriffe auf dem Target umsetzt.\n</li><li><strong>Port <code>pt_Ta</code>:</strong> Prozedurbasierter TTCN-3 Kommunikationsport (Procedure-based Port) zwischen Testfall und Target Adapter.\n</li><li><strong>Prozedur <code>TA_WriteMemBlock</code>:</strong> Prozeduraufruf (Remote Procedure Call) zur Übergabe von Schreibdaten und Adressierungs-/Blockinformationen an den Zielspeicher.\n</li><li><strong>Timer <code>t_guardtimer</code>:</strong> Guard-/Watchdog-Timer zur Laufzeitüberwachung der Operation (initialer Grenzwert: 30,0 s).\n</li><li><strong>Match-Knoten <code>match</code>:</strong> TTCN-3 Evaluierungs- und Verifikationsschritt für die empfangene Prozedurantwort gegen das definierte Soll-Template.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Timer-Start:</strong> Die Testkomponente startet den Schutz-Timer mit einem Worst-Case-Limit von 30 Sekunden (<code>t_guardtimer(30.0)</code>), um Deadlocks oder Hänger des Targets abzufangen.\n</li><li><strong>Prozeduraufruf:</strong> Auslösen des synchronen Prozeduraufrufs <code>call TA_WriteMemBlock</code> über Port <code>pt_Ta</code> an das Testziel.\n</li><li><strong>Target-Abarbeitung:</strong> Der Target Adapter führt den Schreibvorgang im referenzierten Zielspeicherblock aus.\n</li><li><strong>Antwortempfang:</strong> Die Testkomponente empfängt die Rückmeldung des Targets über <code>get reply TA_WriteMemBlock</code> an Port <code>pt_Ta</code>.\n</li><li><strong>Ergebnisprüfung:</strong> Auswertung des Antwortwerts über die Match-Bedingung <code>match TA_WriteMemBlock</code>. Bei Übereinstimmung erfolgt der Log-Eintrag: <code>&quot;TA_WriteMemBlock: Memory Block successfully written&quot;</code>.\n</li><li><strong>Timer-Stopp:</strong> Der Guard-Timer wird erfolgreich vor Ablauf gestoppt (<code>stop t_guardtimer</code>), im Trace mit einer Dauer von 0,21 s erfasst (<code>t_guardtimer(0.21)</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präkondition:</strong> Vor Aufruf von <code>TA_WriteMemBlock</code> muss der Zielspeicherblock erfolgreich über die Allokationssequenz (<code>TA_AllocateMemBlock</code>, Fig. 16) reserviert worden sein. Ein Schreibzugriff auf ungültige Deskriptoren führt zum Fehlschlag des Testfalls.\n</li><li><strong>Schnittstellenanforderung an Target Adapter:</strong> Die Implementierung des Target Adapters muss Prozeduraufrufe deterministisch quittieren. Blockierende Zugriffe ohne <code>reply</code> lösen nach 30,0 s einen Guard-Timeout aus, was das Testurteil auf <code>fail</code> bzw. <code>inconc</code> setzt.\n</li><li><strong>BSW-Speicherstack-Bezug:</strong> Bei Validierung von Speichermodulen (z. B. NvM, Fee, Fls oder dedizierten RAM-Puffern) dient diese Sequenz als Stimulations- oder Verifikationsschritt, um Speicherinhalte vor oder nach Testläufen definiert zu manipulieren, ohne den regulären Treiber-/Stackzustand unkontrolliert zu korrumpieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-63bdb9c33be2c28e", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm im TTCN-3 Graphical Presentation Format (GFT) / Message Sequence Chart (MSC).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation eines Interaktionsmusters im AUTOSAR Conformance Testing Framework (Dokument: <code>AUTOSAR_CTSpec_Creation_Validation</code>, Release R3.0.7). Das Diagramm definiert den normativen Ablauf für das synchrone Beschreiben eines zuvor auf dem Testziel (SUT) allokierten Speicherblocks über den Target Adapter (TA).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Test Component / Test Case (Rechte Lebenslinie):</strong> Führende Testkomponente (MTC/PTC), die den Testablauf steuert, Timeouts überwacht und Rückgabewerte verifiziert.\n</li><li><strong>Target Adapter / SUT (Linke Lebenslinie):</strong> Testadapter-Schicht auf Zielsystemebene, die Testprozeduren in konkrete Speicherzugriffe auf dem Target umsetzt.\n</li><li><strong>Port <code>pt_Ta</code>:</strong> Prozedurbasierter TTCN-3 Kommunikationsport (Procedure-based Port) zwischen Testfall und Target Adapter.\n</li><li><strong>Prozedur <code>TA_WriteMemBlock</code>:</strong> Prozeduraufruf (Remote Procedure Call) zur Übergabe von Schreibdaten und Adressierungs-/Blockinformationen an den Zielspeicher.\n</li><li><strong>Timer <code>t_guardtimer</code>:</strong> Guard-/Watchdog-Timer zur Laufzeitüberwachung der Operation (initialer Grenzwert: 30,0 s).\n</li><li><strong>Match-Knoten <code>match</code>:</strong> TTCN-3 Evaluierungs- und Verifikationsschritt für die empfangene Prozedurantwort gegen das definierte Soll-Template.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Timer-Start:</strong> Die Testkomponente startet den Schutz-Timer mit einem Worst-Case-Limit von 30 Sekunden (<code>t_guardtimer(30.0)</code>), um Deadlocks oder Hänger des Targets abzufangen.\n</li><li><strong>Prozeduraufruf:</strong> Auslösen des synchronen Prozeduraufrufs <code>call TA_WriteMemBlock</code> über Port <code>pt_Ta</code> an das Testziel.\n</li><li><strong>Target-Abarbeitung:</strong> Der Target Adapter führt den Schreibvorgang im referenzierten Zielspeicherblock aus.\n</li><li><strong>Antwortempfang:</strong> Die Testkomponente empfängt die Rückmeldung des Targets über <code>get reply TA_WriteMemBlock</code> an Port <code>pt_Ta</code>.\n</li><li><strong>Ergebnisprüfung:</strong> Auswertung des Antwortwerts über die Match-Bedingung <code>match TA_WriteMemBlock</code>. Bei Übereinstimmung erfolgt der Log-Eintrag: <code>&quot;TA_WriteMemBlock: Memory Block successfully written&quot;</code>.\n</li><li><strong>Timer-Stopp:</strong> Der Guard-Timer wird erfolgreich vor Ablauf gestoppt (<code>stop t_guardtimer</code>), im Trace mit einer Dauer von 0,21 s erfasst (<code>t_guardtimer(0.21)</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präkondition:</strong> Vor Aufruf von <code>TA_WriteMemBlock</code> muss der Zielspeicherblock erfolgreich über die Allokationssequenz (<code>TA_AllocateMemBlock</code>, Fig. 16) reserviert worden sein. Ein Schreibzugriff auf ungültige Deskriptoren führt zum Fehlschlag des Testfalls.\n</li><li><strong>Schnittstellenanforderung an Target Adapter:</strong> Die Implementierung des Target Adapters muss Prozeduraufrufe deterministisch quittieren. Blockierende Zugriffe ohne <code>reply</code> lösen nach 30,0 s einen Guard-Timeout aus, was das Testurteil auf <code>fail</code> bzw. <code>inconc</code> setzt.\n</li><li><strong>BSW-Speicherstack-Bezug:</strong> Bei Validierung von Speichermodulen (z. B. NvM, Fee, Fls oder dedizierten RAM-Puffern) dient diese Sequenz als Stimulations- oder Verifikationsschritt, um Speicherinhalte vor oder nach Testläufen definiert zu manipulieren, ohne den regulären Treiber-/Stackzustand unkontrolliert zu korrumpieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d3ba2ba664e307f3", "to": "FIG-63bdb9c33be2c28e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
